sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 shadowTint;
uniform float shadowAmt;
layout(color) uniform half4 midTint;
uniform float midAmt;
layout(color) uniform half4 highTint;
uniform float highAmt;
uniform float balance;
uniform float preserve;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float l = luma(s);
    float edge = 0.5 + balance * 0.35;
    float sw = 1.0 - smoothstep(0.0, edge, l);
    float hw = smoothstep(edge, 1.0, l);
    float mw = saturate(1.0 - sw - hw);
    float3 sc = float3(shadowTint.rgb);
    float3 mc = float3(midTint.rgb);
    float3 hc = float3(highTint.rgb);
    float3 o = s + (sc - luma(sc)) * shadowAmt * sw + (mc - luma(mc)) * midAmt * mw + (hc - luma(hc)) * highAmt * hw;
    if (preserve > 0.5) o *= l / max(luma(o), 0.0001);
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
